function getItalianCategoryName(item){return ITALIAN_CATEGORY_NAMES[String(item?.type||"")]||item?.type||"";}
function getItalianSetName(item){
  const id=Number(item?.id);
  const base=Number.isFinite(id)?String(Math.floor(id/1000)):"";
  if(ITALIAN_SET_BY_BASE_ID[base]) return ITALIAN_SET_BY_BASE_ID[base];
  const raw=String(item?.set||"");
  if(!raw) return "";
  return raw
    .replace(/^set_valentine_(\d+)_(\d+)$/i,"Set di San Valentino $1 $2")
    .replace(/^valentine_(\d+)_set_(\d+)$/i,"Set di San Valentino $1 $2")
    .replace(/^set_valentinesday_(\d+)_(\d+)$/i,"Set di San Valentino $1 $2")
    .replace(/^2018_valentines_set_(\d+)$/i,"Set di San Valentino 2018 $1");
}
